// TH16 v1.00a Extra boss card: st07bs.ecl.txt BossCard5 (1572-1626), 秘儀「後戸の狂言」.
// Sources used: BossCard5 entry/deps BossCard5_at (1628-1658), BossCard5_at2 (1660-1679),
// Boss context 10-111 (entry position/boxes). Extra only, source has no difficulty branch.

// TH16 type 4 / type 8 slots, copied from transcribe/th16/touhou-bullets.ecl.
const TH16_BALL: int = 416;
const TH16_RICE: int = 480;

const TIME_LIMIT: int = 4924;      // 120 shell buffer + 4800 source spell window + 4 launch slack
const OPENING_BUFFER: int = 120;
const SOURCE_LIMIT: int = 4800;    // spellEx/setInterrupt window counted from BossCard5 entry
const SPELL_CARD5: int = 113;      // spellEx(113, 4800, ...)

// BossCard5_at: %B starts at -1.570796f rad and grows by 3.883222f rad per shot.
// 3.883222 rad = 40503.47 BAM; kept in 1/16 BAM so 500 shots do not drift.
const BASE_ANGLE_Q: int = -262144; // -16384 BAM * 16
const STEP_Q: int = 648056;        // 40503.47 * 16

// BossCard5_at EX chain (async=0 => records run one after another; OFFSCREEN keeps running):
// ANIM a=1 (birth retreat, folded into sh_dist below), OFFSCREEN 600, then
// ANGLE_ACCEL 120f +0.01/0.5deg*A, 100f -0.012/1deg*A, 120f +0.01/0.5deg*A, 100f -0.012/1deg*A,
// VELTIME 120f target speed 0 (angle kept), DELETE.
xformdef CARD5_AT(w_half: angle, w_full: angle) {
    offscreen_keep(600);
    set_ang_vel(w_half);
    @120 set_accel(0.01fx);
    set_ang_vel(w_full);
    @100 set_accel(-0.012fx);
    set_ang_vel(w_half);
    @120 set_accel(0.01fx);
    set_ang_vel(w_full);
    @100 set_accel(-0.012fx);
    set_ang_vel(0bam);
    set_accel(0fx);
    @120 step_speed(0fx, 120);
    set_life(1);
}

// Source BossCard5_at: emitter 0, 1-way fixed ring, 500 shots every 2 frames at speed 1.
sub card5_at(sgn: int, shots: int) {
    var w_half: angle = (91 * sgn) as angle;   // 0.017453292 * 0.5 rad * A
    var w_full: angle = (182 * sgn) as angle;  // 0.017453292 * A
    var baseq: int = BASE_ANGLE_Q;
    sh_reset(0);
    sh_sprite(0, TH16_RICE, 2);
    sh_ring(0, 1);
    sh_count(0, 1, 1);
    sh_speed(0, 1fx, 0fx);
    sh_offset(0, 0fx, -24fx);   // etOffset(0, 0, -24)
    sh_dist(0, 12fx);           // etDist 16 minus ANIM a=1 retreat 4*1.0 along the shot angle
    sh_xform(0, CARD5_AT(w_half, w_full));
    for i in 0..shots {
        sh_angle(0, (baseq / 16) as angle, 0deg);
        sh_fire(0);
        baseq = baseq + STEP_Q * sgn;
        wait(2);
    }
}

// Source BossCard5_at2: 5-way aimed ring (etAim 1,2), type 4 color 2, speed 2.5,
// ANIM a=1 only: each bullet is born 4*2.5 = 10px behind along its own angle.
sub card5_aimed_ring() {
    var base: angle = aim_player();
    for i in 0..5 {
        var a: angle = base + (((i * 65536) / 5) as angle);
        _ = fire(TH16_BALL, 2,
                 $self_x - 10fx * cos(a),
                 $self_y - 10fx * sin(a),
                 2.5fx, a, none, none);
    }
}

// Source BossCard5_at2: first wave at +200, then 100 waves every 10 frames.
async sub card5_at2() {
    wait(200);
    for k in 0..100 {
        card5_aimed_ring();
        wait(10);
    }
}

// Source Boss: entry position (0,128), setHurtbox(40,40)/setHitbox(48,48) -> radius *0.5.
async sub card5_boss() {
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(20fx);
    // BossCard5: movePosTime(60, 4, 0, 224); a 60-frame quadratic-out move from the entry point.
    move_to(60, 0fx, 224fx, EASE_QUAD_OUT);
    wait(90);           // BossCard5 time label +90
    var t: int = 90;    // source script clock from the card entry
    var sgn: int = 1;   // source %C = 1.0, flipped after every loop iteration
    while t < SOURCE_LIMIT {
        spawn card5_at2();   // BossCard5_1048: @BossCard5_at2() async
        var shots: int = 500; // source $C = 500
        if t + 1000 > SOURCE_LIMIT {
            // setInterrupt(0,0,4800) cuts the last BossCard5_at mid-way
            shots = (SOURCE_LIMIT - t) / 2;
        }
        card5_at(sgn, shots);   // BossCard5_1048: @BossCard5_at(%C)
        t = t + shots * 2;
        if t >= SOURCE_LIMIT { break; }
        wait(120);
        t = t + 120;
        sgn = 0 - sgn;          // %C = %C * -1
    }
}

async sub card5_pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 2000, 0, 0, 0, card5_boss);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    spell_begin(0, SPELL_CARD5, card5_pattern, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
